-- Faith Changes Everything
-- Journey to Hope - Sequence 8 authoritative content catalog
-- Governing structure: Journey to Hope Structure Rev1.2
-- Progress behavior: J2H Sequence 8 Handbook Rev1.0
--
-- Classification principle:
--   * only designated lowest-level Journey lessons/studies are completion tracked
--   * Pastor Letters, supporting resources, navigation, series containers, major
--     Steps, and internal content sections do not contribute to completion
--
-- The Hope series (1.c) does not provide a separate structural identifier for
-- each seven-part study page. Internal keys 1.c.study-1 through study-7 model
-- those completion-tracked page units while preserving every Rev1.2 source row
-- as a content_section beneath its corresponding study.

alter table public.j2h_content_items
  alter column step_number drop not null;

alter table public.j2h_content_items
  drop constraint if exists j2h_content_items_item_kind_check;

alter table public.j2h_content_items
  add constraint j2h_content_items_item_kind_check check (item_kind in (
    'step','lesson','series','series_lesson','content_section',
    'pastor_letter','supporting_resource','navigation'
  ));

alter table public.j2h_content_items
  drop constraint if exists j2h_content_items_tracking_kind_chk;

alter table public.j2h_content_items
  add constraint j2h_content_items_tracking_kind_chk
  check (not completion_tracked or item_kind in ('lesson', 'series_lesson'));

alter table public.j2h_content_items
  add column if not exists source_revision text,
  add column if not exists source_row integer,
  add column if not exists source_identifier text;

update public.j2h_content_items
set source_revision = coalesce(source_revision, 'J2H Structure Rev1.2');

alter table public.j2h_content_items
  alter column source_revision set default 'J2H Structure Rev1.2',
  alter column source_revision set not null;

